CREATE TABLE "FixtureMaintenancePolicy" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "fixtureDefinitionId" TEXT NOT NULL, "policyType" TEXT NOT NULL CHECK ("policyType" IN ('TIME','CYCLE','PART_COUNT')), "interval" DECIMAL(18,3) NOT NULL CHECK ("interval" > 0), "warningThreshold" DECIMAL(18,3) CHECK ("warningThreshold" IS NULL OR ("warningThreshold" >= 0 AND "warningThreshold" <= "interval")), "enforcement" TEXT NOT NULL DEFAULT 'INFORMATIONAL' CHECK ("enforcement" IN ('INFORMATIONAL','WARNING','BLOCKING')), "revision" INTEGER NOT NULL DEFAULT 1 CHECK ("revision" > 0), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, FOREIGN KEY ("fixtureDefinitionId") REFERENCES "FixtureDefinition"("id") ON DELETE RESTRICT);
CREATE TABLE "FixtureCalibrationPolicy" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "fixtureDefinitionId" TEXT NOT NULL, "intervalDays" INTEGER NOT NULL CHECK ("intervalDays" > 0), "warningDays" INTEGER CHECK ("warningDays" IS NULL OR ("warningDays" >= 0 AND "warningDays" <= "intervalDays")), "enforcement" TEXT NOT NULL DEFAULT 'INFORMATIONAL' CHECK ("enforcement" IN ('INFORMATIONAL','WARNING','BLOCKING')), "certificateRequired" BOOLEAN NOT NULL DEFAULT false, "revision" INTEGER NOT NULL DEFAULT 1 CHECK ("revision" > 0), "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, FOREIGN KEY ("fixtureDefinitionId") REFERENCES "FixtureDefinition"("id") ON DELETE RESTRICT);
CREATE TABLE "FixtureMaintenanceEvent" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "physicalFixtureInstanceId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PLANNED' CHECK ("status" IN ('PLANNED','IN_PROGRESS','COMPLETED','FAILED','CANCELLED')), "maintenanceType" TEXT NOT NULL, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "result" TEXT CHECK ("result" IN ('PASS','FAIL')), "notes" TEXT, "documentId" TEXT, "counterBefore" DECIMAL(18,3), "counterAfter" DECIMAL(18,3), "idempotencyKey" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1 CHECK ("version" > 0), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, FOREIGN KEY ("physicalFixtureInstanceId") REFERENCES "PhysicalFixtureInstance"("id") ON DELETE RESTRICT, UNIQUE ("tenantId", "idempotencyKey"));
CREATE TABLE "FixtureCalibrationRecord" ("id" TEXT PRIMARY KEY, "tenantId" TEXT NOT NULL, "physicalFixtureInstanceId" TEXT NOT NULL, "calibratedAt" TIMESTAMP(3) NOT NULL, "validUntil" TIMESTAMP(3) NOT NULL CHECK ("validUntil" >= "calibratedAt"), "result" TEXT NOT NULL CHECK ("result" IN ('PASS','FAIL')), "certificateDocumentId" TEXT, "reference" TEXT, "provider" TEXT, "invalidatedAt" TIMESTAMP(3), "invalidatedById" TEXT, "invalidationReason" TEXT, "version" INTEGER NOT NULL DEFAULT 1 CHECK ("version" > 0), "idempotencyKey" TEXT NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY ("physicalFixtureInstanceId") REFERENCES "PhysicalFixtureInstance"("id") ON DELETE RESTRICT, UNIQUE ("tenantId", "idempotencyKey"));
CREATE INDEX "FixtureMaintenancePolicy_tenantId_fixtureDefinitionId_isActive_idx" ON "FixtureMaintenancePolicy"("tenantId","fixtureDefinitionId","isActive");
CREATE INDEX "FixtureCalibrationPolicy_tenantId_fixtureDefinitionId_isActive_idx" ON "FixtureCalibrationPolicy"("tenantId","fixtureDefinitionId","isActive");
CREATE INDEX "FixtureMaintenanceEvent_tenantId_physicalFixtureInstanceId_createdAt_idx" ON "FixtureMaintenanceEvent"("tenantId","physicalFixtureInstanceId","createdAt");
CREATE INDEX "FixtureCalibrationRecord_tenantId_physicalFixtureInstanceId_validUntil_idx" ON "FixtureCalibrationRecord"("tenantId","physicalFixtureInstanceId","validUntil");
